(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.2)*12;
  const w1y = Math.cos(y*0.016-t*0.25)*18 + Math.sin(x*0.015+t*0.35)*12;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.01+t*0.15)*25 + Math.cos(sy*0.012-t*0.1)*15;
  const w2y = Math.cos(sy*0.009-t*0.12)*25 + Math.sin(sx*0.011+t*0.18)*15;
  const dx = sx+w2x, dy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.85],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+2)*65, 0.11, 2.1, 0.95],
    [400+Math.cos(t*0.38+1)*95, 200+Math.sin(t*0.58+4)*55, 0.065, 2.4, 1.05]
  ];
  let aS=0, iS=0, hS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((dx-sX)**2+(dy-sY)**2);
    const wave=Math.sin(d*f-t*sp)*w;
    aS+=wave;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    hS+=Math.sin(d*f*1.3-t*sp*0.4+3.0)*w*0.6;
  }
  const n=8;const act=aS/n,inh=iS/n,harm=hS/n;
  const bg=(Math.sin(dx*0.035+dy*0.022+t*0.7)+Math.sin(dx*0.028-dy*0.038+t*0.95))/2
    +Math.sin((dx+dy)*0.11+t*2.2)*0.2+Math.sin((dx-dy)*0.09-t*1.8)*0.2;
  const dist=Math.sqrt((dx-cx)**2+(dy-cy)**2),ang=Math.atan2(dy-cy,dx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*4.5-t*1.0))*0.35;
  const micro=(Math.sin(dx*0.08+dy*0.06+t*1.5)*Math.sin(dx*0.05-dy*0.09-t*1.2)+Math.sin(dx*0.12+t*0.8)*Math.sin(dy*0.1-t*0.6))*0.25;
  const field=act-inh*0.65+bg*0.25+spiral+micro+harm*0.2;
  const reaction=Math.tanh(field*2.0);
  const cell=Math.tanh((Math.sin(dx*0.13)*Math.sin(dy*0.13)+Math.sin((dx+dy)*0.09+t)*0.4+Math.sin(dx*0.07-dy*0.11+t*0.7)*0.3)*1.4)*0.25;
  const blend=reaction*0.7+cell*0.3;
  const v=blend*0.5+0.5;
  const glow=Math.exp(-Math.abs(reaction)*1.5)*0.3;
  const edge=Math.abs(reaction)>0.65?1.0+glow:1.0;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18+glow*0.5;
  const pal=[
    [5,12,52],[10,45,85],[15,90,115],[20,140,130],[45,170,120],
    [120,185,80],[195,175,55],[220,140,50],[210,95,60],[180,55,65],
    [130,35,75],[75,22,58],[30,15,48],[5,12,52]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge)|0
  ];
}
